<script setup>
import { ref, computed, inject, onBeforeUnmount, watch } from 'vue'
import { useRoute } from 'vue-router'
import { navigation } from '../navigation'
import { filterSensors, sensorHealth } from '../sensors'
import TrendChart from '../components/TrendChart.vue'
const route = useRoute(), dataApi = inject('dataApi'), block = inject('workspace-block'), dark = inject('workspace-theme')
const data = ref(structuredClone(dataApi.projectData)), search = ref(''), systemFilter = ref('all'), status = ref('all'), selectedId = ref('')
const unsubscribe = dataApi.subscribeData(next => { data.value = structuredClone(next) }); onBeforeUnmount(unsubscribe)
const system = computed(() => route.meta.section), nav = computed(() => navigation.find(n => n.id === system.value))
const scope = computed(() => filterSensors(data.value.sensors, system.value, block.value))
const visible = computed(() => filterSensors(data.value.sensors, system.value, block.value, status.value, search.value).filter(s => systemFilter.value === 'all' || s.systemId === systemFilter.value))
const systemOptions = computed(() => data.value.systems.filter(s => s.category === system.value && (block.value === 'all' || s.locationIds.includes(block.value))))
const selected = computed(() => visible.value.find(s => s.id === selectedId.value) || visible.value[0])
const counts = computed(() => Object.fromEntries(['Normal','Abnormal','Faulty','Offline'].map(label => [label, scope.value.filter(s => sensorHealth(s).status === label).length])))
const unit = computed(() => system.value === 'energy' ? 'kWh' : 'm³'), rateUnit = computed(() => system.value === 'energy' ? 'kW' : 'm³/h')
const fmt = value => Number.isFinite(value) ? value.toLocaleString('en-SG', { maximumFractionDigits: 2 }) : 'Unavailable'
const date = value => new Date(value).toLocaleString('en-SG', { timeZone:'Asia/Singapore' }) + ' SGT'
watch(system, () => { search.value = ''; systemFilter.value = 'all'; status.value = 'all'; selectedId.value = '' })
watch(block, () => { systemFilter.value = 'all' })
</script>
<template>
  <main class="sensors-page">
    <div class="page-heading"><div><p class="eyebrow">METER HEALTH &amp; USAGE</p><h1>{{ nav.label }} sensors</h1><p class="subtitle">Inspect individual meters, consumption and operating exceptions.</p></div><RouterLink class="threshold-link" :to="nav.path">Back to overview</RouterLink></div>
    <div class="sensor-summary"><section v-for="label in ['Normal','Abnormal','Faulty','Offline']" :key="label" class="card"><span :class="`sensor-status ${label.toLowerCase()}`">{{ label }}</span><strong>{{ counts[label] }}</strong><small>meters in selected locations</small></section></div>
    <section class="card sensor-inventory"><div class="card-heading"><h2>Sensor inventory <span class="tag">{{ visible.length }} meters</span></h2><RouterLink class="threshold-link" :to="nav.path + '/thresholds'">Thresholds &amp; alerts</RouterLink></div><div class="sensor-filters"><label>Search sensors<input v-model="search" placeholder="Sensor ID, location or name" aria-label="Search sensors"></label><label>Location<select v-model="block" aria-label="Sensor location"><option value="all">All locations</option><option v-for="b in data.blocks" :key="b.id" :value="b.id">{{ b.name }}</option></select></label><label>System<select v-model="systemFilter" aria-label="Sensor system"><option value="all">All systems</option><option v-for="s in systemOptions" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label>Status<select v-model="status" aria-label="Sensor status"><option value="all">All statuses</option><option v-for="label in ['Normal','Abnormal','Faulty','Offline']" :key="label">{{ label }}</option></select></label></div>
      <div class="table-scroll"><table><thead><tr><th>Sensor / location</th><th>Location</th><th>Health</th><th>Current rate ({{ rateUnit }})</th><th>Today ({{ unit }})</th><th>Totalizer ({{ unit }})</th><th>Last communication</th><th>Inspect</th></tr></thead><tbody><tr v-for="sensor in visible" :key="sensor.id" :class="{ 'sensor-selected': selected?.id === sensor.id }"><td><strong>{{ sensor.name }}</strong><small class="asset-id">{{ sensor.id }} · {{ sensor.location }}</small></td><td>{{ data.blocks.find(b => b.id === sensor.blockId)?.name }}</td><td><span :class="`sensor-status ${sensorHealth(sensor).status.toLowerCase()}`">{{ sensorHealth(sensor).status }}</span></td><td>{{ fmt(sensor.online && !sensor.faultCode ? sensor.rate : null) }}</td><td>{{ fmt(sensor.today) }}<small v-if="!sensor.online || sensor.faultCode" class="asset-id">Last recorded demo value</small></td><td>{{ fmt(sensor.cumulative) }}</td><td>{{ date(sensor.lastSeen) }}</td><td><button :aria-label="`Inspect ${sensor.id}`" :aria-pressed="selected?.id === sensor.id" @click="selectedId = sensor.id">Details</button></td></tr></tbody></table></div><p v-if="!visible.length" class="no-assets">No sensors match these filters.</p><p class="range-availability">Demo snapshot: 12 Oct 2026. These meters measure consumption, not energy generation or water production. Totalizers are cumulative demo readings.</p>
    </section>
    <section v-if="selected" class="sensor-detail" :key="selected.id" aria-label="Selected sensor details"><div class="card sensor-diagnostics"><div class="card-heading"><h2>{{ selected.name }}</h2><span :class="`sensor-status ${sensorHealth(selected).status.toLowerCase()}`">{{ sensorHealth(selected).status }}</span></div><p>{{ sensorHealth(selected).detail }}</p><dl><div><dt>System</dt><dd>{{ selected.systemName }}</dd></div><div><dt>Sensor ID</dt><dd>{{ selected.id }}</dd></div><div><dt>3D model node</dt><dd>{{ selected.modelNode }}</dd></div><div><dt>Current usage rate</dt><dd>{{ fmt(selected.online && !selected.faultCode ? selected.rate : null) }} {{ selected.online && !selected.faultCode && selected.rate !== null ? rateUnit : '' }}</dd></div><div><dt>Demo expected maximum</dt><dd>{{ selected.expectedMaxRate }} {{ rateUnit }}</dd></div><div><dt>Fault code</dt><dd>{{ selected.faultCode || 'None reported' }}</dd></div><div><dt>Last communication</dt><dd>{{ date(selected.lastSeen) }}</dd></div></dl><p class="range-availability">Sensor diagnostics use connectivity, reported faults and each meter’s expected usage rate. System thresholds remain separate block-level alert rules.</p></div><div class="card sensor-chart"><div class="card-heading"><h2>Individual sensor consumption history</h2><span class="tag">Demo history</span></div><TrendChart :widget="{title: 'Sensor consumption', type:'line', series:system, unit, totalLabel:'Selected sensor consumption'}" :blocks="[{id:selected.id, name:selected.id}]" :trends="{periods:selected.history}" :dark="dark"/><p class="range-availability">Profiles are allocated from demo block history; they are not actual recorded meter telemetry. Historical values remain available when a sensor is currently offline or faulty.</p></div></section>
  </main>
</template>
